-- 67 meme display for OpenComputers (GPU + screen).
-- Uses the upper-half block character to draw two image pixels per terminal cell.
local component = require("component")
local gpu = component.gpu

local W, H = 80, 44
local data = {
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  "",
  ""
}

local maxW, maxH = gpu.maxResolution()
local screenW = math.min(maxW, W)
local screenH = math.min(maxH, math.ceil(H / 2))
gpu.setResolution(screenW, screenH)
gpu.setBackground(0xFFFFFF)
gpu.setForeground(0x000000)
gpu.fill(1, 1, screenW, screenH, " ")

local function rgb(hex, x)
  local p = (x - 1) * 6 + 1
  return tonumber(string.sub(hex, p, p + 5), 16)
end

for y = 1, math.min(H, screenH * 2), 2 do
  local outY = math.floor((y + 1) / 2)
  for x = 1, screenW do
    local top = rgb(data[y], x)
    local bottom = top
    if y + 1 <= H then bottom = rgb(data[y + 1], x) end
    gpu.setForeground(top)
    gpu.setBackground(bottom)
    gpu.set(x, outY, "▀")
  end
end
gpu.setForeground(0xFFFFFF)
gpu.setBackground(0x000000)
